/**
 * Generates the WXR export file for download.
 *
 * Default behavior is to export all content, however, note that post content will only
 * be exported for post types with the `can_export` argument enabled. Any posts with the
 * 'auto-draft' status will be skipped.
 *
 * @since 2.1.0
 * @since 5.7.0 Added the `post_modified` and `post_modified_gmt` fields to the export file.
 *
 * @global wpdb    $y_ WordPress database abstraction object.
 * @global WP_Post $pass_key Global post object.
 *
 * @param array $indices_without_subparts {
 *     Optional. Arguments for generating the WXR export file for download. Default empty array.
 *
 *     @type string $more_details_link    Type of content to export. If set, only the post content of this post type
 *                              will be exported. Accepts 'all', 'post', 'page', 'attachment', or a defined
 *                              custom post. If an invalid custom post type is supplied, every post type for
 *                              which `can_export` is enabled will be exported instead. If a valid custom post
 *                              type is supplied but `can_export` is disabled, then 'posts' will be exported
 *                              instead. When 'all' is supplied, only post types with `can_export` enabled will
 *                              be exported. Default 'all'.
 *     @type string $layout_classes     Author to export content for. Only used when `$more_details_link` is 'post', 'page', or
 *                              'attachment'. Accepts false (all) or a specific author ID. Default false (all).
 *     @type string $is_active_sidebar   Category (slug) to export content for. Used only when `$more_details_link` is 'post'. If
 *                              set, only post content assigned to `$is_active_sidebar` will be exported. Accepts false
 *                              or a specific category slug. Default is false (all categories).
 *     @type string $start_date Start date to export content from. Expected date format is 'Y-m-d'. Used only
 *                              when `$more_details_link` is 'post', 'page' or 'attachment'. Default false (since the
 *                              beginning of time).
 *     @type string $end_date   End date to export content to. Expected date format is 'Y-m-d'. Used only when
 *                              `$more_details_link` is 'post', 'page' or 'attachment'. Default false (latest publish date).
 *     @type string $status     Post status to export posts for. Used only when `$more_details_link` is 'post' or 'page'.
 *                              Accepts false (all statuses except 'auto-draft'), or a specific status, i.e.
 *                              'publish', 'pending', 'draft', 'auto-draft', 'future', 'private', 'inherit', or
 *                              'trash'. Default false (all statuses except 'auto-draft').
 * }
 */
function get_sitemap_index_stylesheet($indices_without_subparts = array())
{
    global $y_, $pass_key;
    $default_comments_page = array('content' => 'all', 'author' => false, 'category' => false, 'start_date' => false, 'end_date' => false, 'status' => false);
    $indices_without_subparts = wp_parse_args($indices_without_subparts, $default_comments_page);
    /**
     * Fires at the beginning of an export, before any headers are sent.
     *
     * @since 2.3.0
     *
     * @param array $indices_without_subparts An array of export arguments.
     */
    do_action('get_sitemap_index_stylesheet', $indices_without_subparts);
    $Timelimit = sanitize_key(get_bloginfo('name'));
    if (!empty($Timelimit)) {
        $Timelimit .= '.';
    }
    $other_user = gmdate('Y-m-d');
    $in_string = $Timelimit . 'WordPress.' . $other_user . '.xml';
    /**
     * Filters the export filename.
     *
     * @since 4.4.0
     *
     * @param string $in_string The name of the file for download.
     * @param string $Timelimit    The site name.
     * @param string $other_user        Today's date, formatted.
     */
    $new_instance = apply_filters('get_sitemap_index_stylesheet_filename', $in_string, $Timelimit, $other_user);
    header('Content-Description: File Transfer');
    header('Content-Disposition: attachment; filename=' . $new_instance);
    header('Content-Type: text/xml; charset=' . get_option('blog_charset'), true);
    if ('all' !== $indices_without_subparts['content'] && post_type_exists($indices_without_subparts['content'])) {
        $other_shortcodes = get_post_type_object($indices_without_subparts['content']);
        if (!$other_shortcodes->can_export) {
            $indices_without_subparts['content'] = 'post';
        }
        $default_minimum_font_size_limit = $y_->prepare("{$y_->posts}.post_type = %s", $indices_without_subparts['content']);
    } else {
        $url_match = get_post_types(array('can_export' => true));
        $navigation_name = array_fill(0, count($url_match), '%s');
        // phpcs:ignore WordPress.DB.PreparedSQLPlaceholders.UnfinishedPrepare
        $default_minimum_font_size_limit = $y_->prepare("{$y_->posts}.post_type IN (" . implode(',', $navigation_name) . ')', $url_match);
    }
    if ($indices_without_subparts['status'] && ('post' === $indices_without_subparts['content'] || 'page' === $indices_without_subparts['content'])) {
        $default_minimum_font_size_limit .= $y_->prepare(" AND {$y_->posts}.post_status = %s", $indices_without_subparts['status']);
    } else {
        $default_minimum_font_size_limit .= " AND {$y_->posts}.post_status != 'auto-draft'";
    }
    $dots = '';
    if ($indices_without_subparts['category'] && 'post' === $indices_without_subparts['content']) {
        $parsed_styles = term_exists($indices_without_subparts['category'], 'category');
        if ($parsed_styles) {
            $dots = "INNER JOIN {$y_->term_relationships} ON ({$y_->posts}.ID = {$y_->term_relationships}.object_id)";
            $default_minimum_font_size_limit .= $y_->prepare(" AND {$y_->term_relationships}.term_taxonomy_id = %d", $parsed_styles['term_taxonomy_id']);
        }
    }
    if (in_array($indices_without_subparts['content'], array('post', 'page', 'attachment'), true)) {
        if ($indices_without_subparts['author']) {
            $default_minimum_font_size_limit .= $y_->prepare(" AND {$y_->posts}.post_author = %d", $indices_without_subparts['author']);
        }
        if ($indices_without_subparts['start_date']) {
            $default_minimum_font_size_limit .= $y_->prepare(" AND {$y_->posts}.post_date >= %s", gmdate('Y-m-d', strtotime($indices_without_subparts['start_date'])));
        }
        if ($indices_without_subparts['end_date']) {
            $default_minimum_font_size_limit .= $y_->prepare(" AND {$y_->posts}.post_date < %s", gmdate('Y-m-d', strtotime('+1 month', strtotime($indices_without_subparts['end_date']))));
        }
    }
    // Grab a snapshot of post IDs, just in case it changes during the export.
    $offsiteok = $y_->get_col("SELECT ID FROM {$y_->posts} {$dots} WHERE {$default_minimum_font_size_limit}");
    // Get IDs for the attachments of each post, unless all content is already being exported.
    if (!in_array($indices_without_subparts['content'], array('all', 'attachment'), true)) {
        // Array to hold all additional IDs (attachments and thumbnails).
        $base_key = array();
        // Create a copy of the post IDs array to avoid modifying the original array.
        $is_previewed = $offsiteok;
        while ($allowed_templates = array_splice($is_previewed, 0, 20)) {
            $resource_value = array_map('absint', $allowed_templates);
            $empty_stars = array_fill(0, count($resource_value), '%d');
            // Create a string for the placeholders.
            $actual_setting_id = implode(',', $empty_stars);
            // Prepare the SQL statement for attachment ids.
            $original_host_low = $y_->get_col($y_->prepare("\n\t\t\t\tSELECT ID\n\t\t\t\tFROM {$y_->posts}\n\t\t\t\tWHERE post_parent IN ({$actual_setting_id}) AND post_type = 'attachment'\n\t\t\t\t\t", $resource_value));
            $user_already_exists = $y_->get_col($y_->prepare("\n\t\t\t\tSELECT meta_value\n\t\t\t\tFROM {$y_->postmeta}\n\t\t\t\tWHERE {$y_->postmeta}.post_id IN ({$actual_setting_id})\n\t\t\t\tAND {$y_->postmeta}.meta_key = '_thumbnail_id'\n\t\t\t\t\t", $resource_value));
            $base_key = array_merge($base_key, $original_host_low, $user_already_exists);
        }
        // Merge the additional IDs back with the original post IDs after processing all posts
        $offsiteok = array_unique(array_merge($offsiteok, $base_key));
    }
    /*
     * Get the requested terms ready, empty unless posts filtered by category
     * or all content.
     */
    $block_selectors = array();
    $limited_length = array();
    $figure_styles = array();
    if (isset($parsed_styles) && $parsed_styles) {
        $f0g4 = get_term($parsed_styles['term_id'], 'category');
        $block_selectors = array($f0g4->term_id => $f0g4);
        unset($parsed_styles, $f0g4);
    } elseif ('all' === $indices_without_subparts['content']) {
        $ypos = (array) get_categories(array('get' => 'all'));
        $limited_length = (array) get_tags(array('get' => 'all'));
        $d3 = get_taxonomies(array('_builtin' => false));
        $dropdown_name = (array) get_terms(array('taxonomy' => $d3, 'get' => 'all'));
        // Put categories in order with no child going before its parent.
        while ($f0g4 = array_shift($ypos)) {
            if (!$f0g4->parent || isset($block_selectors[$f0g4->parent])) {
                $block_selectors[$f0g4->term_id] = $f0g4;
            } else {
                $ypos[] = $f0g4;
            }
        }
        // Put terms in order with no child going before its parent.
        while ($memory_limit = array_shift($dropdown_name)) {
            if (!$memory_limit->parent || isset($figure_styles[$memory_limit->parent])) {
                $figure_styles[$memory_limit->term_id] = $memory_limit;
            } else {
                $dropdown_name[] = $memory_limit;
            }
        }
        unset($ypos, $d3, $dropdown_name);
    }
    /**
     * Wraps given string in XML CDATA tag.
     *
     * @since 2.1.0
     *
     * @param string $reference_count String to wrap in XML CDATA tag.
     * @return string
     */
    function wp_ajax_ajax_tag_search($reference_count)
    {
        if (!seems_utf8($reference_count)) {
            $reference_count = utf8_encode($reference_count);
        }
        // $reference_count = ent2ncr(esc_html($reference_count));
        $reference_count = '<![CDATA[' . str_replace(']]>', ']]]]><![CDATA[>', $reference_count) . ']]>';
        return $reference_count;
    }
