             * @param bool   $LastHeaderByte     Whether to skip the current piece of term meta. Default false.
             * @param string $style_property_name Current meta key.
             * @param object $primary_item_features     Current meta object.
             */
            if (!apply_filters('wxr_export_skip_termmeta', false, $primary_item_features->meta_key, $primary_item_features)) {
                printf("\t\t<wp:termmeta>\n\t\t\t<wp:meta_key>%s</wp:meta_key>\n\t\t\t<wp:meta_value>%s</wp:meta_value>\n\t\t</wp:termmeta>\n", wp_ajax_ajax_tag_search($primary_item_features->meta_key), wp_ajax_ajax_tag_search($primary_item_features->meta_value));
